#include <bits/stdc++.h>
using namespace std;

int n;
vector<vector<int>> adj;
vector<int> sz;
long long best = LLONG_MAX;

void dfs(int u, int p) {
    sz[u] = 1;
    for (int v : adj[u]) {
        if (v == p) continue;
        dfs(v, u);
        sz[u] += sz[v];
    }
    if (p != -1) {
        long long diff = (long long)n - 2LL * sz[u];
        if (diff < 0) diff = -diff;
        best = min(best, diff);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    adj.assign(n + 1, {});
    sz.assign(n + 1, 0);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    if (n == 2) {
        cout << 0 << "\n";
        return 0;
    }
    dfs(1, -1);
    cout << best << "\n";
    return 0;
}
